fd:scripts.fd:valueCommit:
[{
    "enabled": false\,
    "nodeName": "SCRIPTMODEL"\,
    "script": {
        "content": "var formMetadata = window.forms.ubs.getFormMetadata();\\nvar currLanguage = formMetadata.language || 'EN';\\nvar currEntity = formMetadata.mandator || '001';\\ncurrLanguage = (currLanguage.toLowerCase() == \\"es\\" ? \\"SP\\" : currLanguage);\\nvar newText = this.parent.INFO_printBlank.myInfo2.value.replace(\\"AAAA\\"\, TXT_FormCode.value).replace(\\"language=DE\\"\, \\"language=\\" + currLanguage).replace(\\"entity=001\\"\, \\"entity=\\" + currEntity).replace(\\"format=XFA\\"\, \\"format=\\" +  this.parent.TXT_Format.value).replace(\\"00000\\"\, this.value);\\n\\n$('.INFO_printBlank').html(newText);\\n\\n//this.dorExclusion = true;"\,
        "event": "Value Commit"\,
        "field": "guide.guideRootPanel.step_1.Client_details.PN_PrintBlank.TXT_CDOK"
    }\,
    "version": 1
}]

[{
    "enabled": true\,
    "nodeName": "SCRIPTMODEL"\,
    "script": {
        "content": "// For Country Dropdown\\nvar metadata = window.forms.ubs.getFormMetadata();\\nvar clientType = this.value === \\"2\\" ? \\"DOMICILE_COMPANY\\" : \\"DOMICILE_INDIVIDUAL\\";\\nwindow.forms.ubs.referencedata.getCountryList(metadata.mandator\, metadata.language\, clientType\, PN_AddressBlock.DD_Country_AddressBlock);"\,
        "event": "Value Commit"\,
        "field": "guide.guideRootPanel.step_1.Client_details.contentPanel_nameCompany.RB_CPType"\,
        "model": {
            "nodeName": "EVENT_SCRIPTS"
        }
    }\,
    "version": 1
},{
    "enabled": true\,
    "nodeName": "SCRIPTMODEL"\,
    "script": {
        "content": "/** For Signature Section **/\\nif(this.value === \\"2\\"){\\t/** company case **/  \\n  PN_SGN_CPG.resetData();\\n  \\n  window.forms.ubs.hideAFHideDor(PN_SGN_CPG);\\n  window.forms.ubs.showAFShowDor(PN_SGN_AR);\\n\\n} else if(this.value === \\"1\\"){\\t/** individual case **/ \\n  window.forms.ubs.resetAllPanelInstances(PN_SGN_ARGRP);\\n  \\n  window.forms.ubs.hideAFHideDor(PN_SGN_AR);\\n  window.forms.ubs.showAFShowDor(PN_SGN_CPG);\\n}"\,
        "event": "Value Commit"\,
        "field": "guide.guideRootPanel.step_1.Client_details.contentPanel_nameCompany.RB_CPType"
    }\,
    "version": 1
},{
    "enabled": true\,
    "nodeName": "SCRIPTMODEL"\,
    "script": {
        "content": "/** For Account Holder Section **/\\nvar pnIndividual = PN_CPG.PN_IndividualBasic;\\nvar pnCompany = PN_CPG.PN_EntityBasic; \\n\\nif(this.value === \\"2\\"){\\t/** company **/     \\n  try{\\n    if(rbclientTypeVal!=this.value){        \\n      PN_CPG.resetData();\\n    } \\n  } catch(e){}\\n  window.forms.ubs.hideAFHideDor(pnIndividual);\\n  window.forms.ubs.showAFShowDor(pnCompany);\\n\\n  rbclientTypeVal = 2;\\n\\n} else if(this.value ===\\"1\\"){\\t/** individual-default **/ \\n  try{\\n    if(rbclientTypeVal!=this.value){        \\n      PN_CPG.resetData();\\n    } \\n  } catch(e){}\\n  window.forms.ubs.hideAFHideDor(pnCompany);\\n  window.forms.ubs.showAFShowDor(pnIndividual);\\n\\n  rbclientTypeVal = 1;  \\n}"\,
        "event": "Value Commit"\,
        "field": "guide.guideRootPanel.step_1.Client_details.contentPanel_nameCompany.RB_CPType"
    }\,
    "version": 1
}]

