},{
    "enabled": true\,
    "nodeName": "SCRIPTMODEL"\,
    "script": {
        "content": "var lenAHRP = PN_AHRP.instanceManager.instances.length;\\n\\nfor(var i = 0; i < lenAHRP; i++){\\n  PN_AHRP.instanceManager.instances[i].BT_RemoveAH.visible =  (i === (lenAHRP-1) && lenAHRP > 1 ) ? true : false;\\n}\\n\\nBT_AddAH.visible = true;\\n\\nif(lenAHRP === 1) {     \\n  PN_AHRP.instanceManager.instances[0].ST_Subtitle0.visible = true;\\n  PN_AHRP.instanceManager.instances[0].ST_Subtitle0.dorExclusion = false;  \\n  PN_AHRP.instanceManager.instances[0].ST_Subtitle1.visible = false;\\n  PN_AHRP.instanceManager.instances[0].ST_Subtitle1.dorExclusion = true;\\n  \\n  // Signature section handling\\n  PN_Sign_AHRP.instanceManager.instances[0].ST_AH0.visible = true;\\n  PN_Sign_AHRP.instanceManager.instances[0].ST_AH0.dorExclusion = false;\\n  PN_Sign_AHRP.instanceManager.instances[0].ST_AH1.visible = false;\\n  PN_Sign_AHRP.instanceManager.instances[0].ST_AH1.dorExclusion = true;\\n\\n} "\,
        "event": "Click"\,
        "field": "guide.guideRootPanel.PN_Step_AH.PN_AHRP.BT_RemoveAH"
    }\,
    "version": 1
}]

